import { useState } from "react";
import useHttp from "./use_http";
import { useFormik } from "formik";
import { createBalanceSchema } from "../utility/schemas";
import toast from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { setDeleteModal, setSelectedBalance } from "../redux/balances_slice";

const useBalance = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { httpService } = useHttp();

  const [balanceLoadings, setBalanceLoadings] = useState({
    getBalances: false,
    createBalance: false,
    deleteBalance: false,
  });
  const [balancePaginates, setBalancePaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    type: null,
    timeframe: null,
    roaming_balance: null,
  });

  const [balanceList, setBalanceList] = useState([]);

  const getBalances = async (page, filtersData) => {
    let array = [];

    const paramsData = {
      page: page,
    };
    if (filtersData.type) {
      paramsData["type"] = filtersData?.type?.value;
    }
    if (filtersData.timeframe) {
      paramsData["timeframe"] = filtersData?.timeframe?.value;
    }

    if (filtersData?.roaming_balance?.value === "roaming") {
      paramsData["roaming_balance"] = true;
    }

    try {
      setBalanceLoadings({ ...balanceLoadings, getBalances: true });
      const response = await httpService.get(`/v1/balances`, {
        params: paramsData,
      });
      setBalanceLoadings({ ...balanceLoadings, getBalances: false });
      setBalancePaginates({
        ...balancePaginates,
        current: response.data.meta.page,
        total: response.data.meta.pages,
        per_page: response.data.meta.limit,
      });
      if (response.data.data) {
        response.data.data.map((item) => {
          if (
            item.Name !== "credit_default_monetary" &&
            item.Name !== "permanent_default_monetary"
          ) {
            array.push(item);
          }
        });
        setBalanceList(array);
      } else {
        setBalanceList([]);
      }
    } catch ({ err, response }) {
      setBalanceLoadings({ ...balanceLoadings, getBalances: false });
    }
  };

  const createBalanceController = useFormik({
    initialValues: {
      name: "",
      persian_name: "",
      type: { label: "data", value: "data" },
      unit: { label: "GB", value: "GB" },
      value: "",
      timeframe: null,
      usable_from: "",
      usable_till: "",
      hours: 0,
      minutes: 0,
      roaming_balance: false,
    },
    validationSchema: createBalanceSchema,
    onSubmit: (values) => {
      createBalance(values);
    },
  });

  const createBalance = async (values) => {
    let postData = {
      name: values.name,
      persian_name: values.persian_name,
      type: values.type?.value,
      timeframe: values.timeframe?.value,
      usable_from: values.usable_from,
      usable_till: values.usable_till,
      roaming_balance: values.roaming_balance,
    };

    let inisdeHours = values.hours;
    let insideMinutes = values.minutes;
    if (values.type.value == "voice" || values.type.value == "video") {
      if (values.hours.length === 0) {
        inisdeHours = 0;
      }
      if (values.minutes.length === 0) {
        insideMinutes = 0;
      }
      if (parseFloat(inisdeHours) == 0 && parseFloat(insideMinutes) == 0) {
        toast.error("Please enter hours or minutes");
      } else if (parseFloat(insideMinutes) > 59) {
        toast.error("Minutes can't be more than 59");
      } else {
        postData["value"] = inisdeHours * 60 * 60 + insideMinutes * 60;
      }
    }

    if (values.type.value == "data") {
      if (values.unit.value == "GB") {
        postData["value"] = values.value * 1024 * 1024 * 1024;
      }
      if (values.unit.value == "MB") {
        postData["value"] = values.value * 1024 * 1024;
      }
      if (values.unit.value == "KB") {
        postData["value"] = values.value * 1024;
      }
    }
    if (postData.value) {
      try {
        setBalanceLoadings({ ...balanceLoadings, createBalance: true });
        const response = await httpService.post(`/v1/balances/`, postData);
        if (response.status == 200 || response.status == 201) {
          setBalanceLoadings({ ...balanceLoadings, createBalance: false });
          toast.success("Balance created successfully");
          navigate("/balances/all");
        } else {
          toast.error(response.data.data);
        }
      } catch ({ err, response }) {
        setBalanceLoadings({ ...balanceLoadings, createBalance: false });
      }
    }
  };

  const deleteBalance = async (balance_name, filtersData) => {
    try {
      setBalanceLoadings({ ...balanceLoadings, deleteBalance: true });
      const response = await httpService.delete(`/v1/balances/${balance_name}`);
      if (response.status === 200 || response.status == 201) {
        setBalanceLoadings({ ...balanceLoadings, deleteBalance: false });
        toast.success("Balance deleted successfully.");
        dispatch(setDeleteModal(null));
        dispatch(setSelectedBalance(null));
        setBalancePaginates({ ...balancePaginates, current: 1 });
        getBalances(1, filtersData);
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setBalanceLoadings({ ...balanceLoadings, deleteBalance: false });
    }
  };

  const exports = {
    getBalances,
    deleteBalance,
    balanceList,
    filters,
    setFilters,
    createBalanceController,
    balancePaginates,
    setBalancePaginates,
    balanceLoadings,
  };
  return exports;
};
export default useBalance;
