import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { useSkin } from "@hooks/useSkin";
import { ChevronDown } from "react-feather";
import { columns } from "./datatable/columns";
import DataTable from "react-data-table-component";
import { useDispatch, useSelector } from "react-redux";
import { setDeleteModal } from "../../../redux/balances_slice";
import toast from "react-hot-toast";
import Confirm from "../../../components/confirm";
import {
  UncontrolledAccordion,
  AccordionItem,
  AccordionHeader,
  AccordionBody,
  Card,
  Row,
  Col,
  Label,
  Button,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import ReactPaginate from "react-paginate";
import useBalance from "../../../hooks/use_balance";
import ProgressLoading from "../../../components/progress_loading";

const AllBalances = () => {
  const { skin } = useSkin();
  const dispatch = useDispatch();
  const {
    getBalances,
    deleteBalance,
    balanceList,
    filters,
    setFilters,
    balancePaginates,
    setBalancePaginates,
    balanceLoadings,
  } = useBalance();

  const deleteModal = useSelector((state) => state.balances.deleteModal);
  const selectedBalance = useSelector(
    (state) => state.balances.selectedBalance
  );

  const handlePagination = (page) => {
    setBalancePaginates({ ...balancePaginates, current: page.selected });
    getBalances(page.selected + 1, filters);
  };

  // ** Custom Pagination
  const CustomPagination = () => (
    <ReactPaginate
      previousLabel=""
      nextLabel=""
      forcePage={balancePaginates.current - 1}
      onPageChange={(page) => handlePagination(page)}
      pageCount={balancePaginates.total}
      breakLabel="..."
      pageRangeDisplayed={2}
      marginPagesDisplayed={2}
      activeClassName="active"
      pageClassName="page-item"
      breakClassName="page-item"
      nextLinkClassName="page-link"
      pageLinkClassName="page-link"
      breakLinkClassName="page-link"
      previousLinkClassName="page-link"
      nextClassName="page-item next-item"
      previousClassName="page-item prev-item"
      containerClassName="pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1"
    />
  );

  useEffect(() => {
    setBalancePaginates({ ...balancePaginates, current: 1 });
    getBalances(1, filters);
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Balances List"
        data={[{ title: "Balances" }, { title: "Balances List" }]}
      />
      {/* filterbar */}
      <Card>
        <UncontrolledAccordion>
          <AccordionItem>
            <AccordionHeader targetId="1">Filters</AccordionHeader>
            <AccordionBody accordionId="1">
              <Row>
                {/* type */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="type">type</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      { label: "video", value: "video" },
                      { label: "voice", value: "voice" },
                      { label: "data", value: "data" },
                      { label: "monetary", value: "monetary" },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="type"
                    name="type"
                    value={filters.type}
                    onChange={(value) =>
                      setFilters({ ...filters, type: value })
                    }
                  />
                </Col>
                {/* timeframe */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="timeframe">timeframe</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      {
                        label: "monthly",
                        value: "monthly",
                      },
                      {
                        label: "weekly",
                        value: "weekly",
                      },
                      {
                        label: "daily",
                        value: "daily",
                      },
                      {
                        label: "unlimited",
                        value: "unlimited",
                      },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="timeframe"
                    name="timeframe"
                    value={filters.timeframe}
                    onChange={(value) =>
                      setFilters({ ...filters, timeframe: value })
                    }
                  />
                </Col>
                {/* roaming_balance */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="roaming_balance">roaming_balance</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      {
                        label: "All",
                        value: "all",
                      },
                      {
                        label: "Roaming",
                        value: "roaming",
                      },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="roaming_balance"
                    name="roaming_balance"
                    value={filters.roaming_balance}
                    onChange={(value) =>
                      setFilters({ ...filters, roaming_balance: value })
                    }
                  />
                </Col>
                {/* actions */}
                <Col xs="12" className={"d-flex justify-content-end"}>
                  <Button
                    style={{ marginRight: 8 }}
                    color="danger"
                    onClick={() => {
                      setBalancePaginates({ ...balancePaginates, current: 1 });
                      getBalances(1, {
                        type: null,
                        timeframe: null,
                        roaming_balance: null,
                      });
                      setFilters({
                        type: null,
                        timeframe: null,
                        roaming_balance: null,
                      });
                    }}
                  >
                    Clear
                  </Button>
                  <Button
                    onClick={() => {
                      setBalancePaginates({ ...balancePaginates, current: 1 });
                      getBalances(1, filters);
                    }}
                    style={{ width: 150 }}
                    color="primary"
                  >
                    Filter
                  </Button>
                </Col>
              </Row>
            </AccordionBody>
          </AccordionItem>
        </UncontrolledAccordion>
      </Card>
      {/* datatable */}
      <div className="react-dataTable mv_datatable_container">
        <DataTable
          noDataComponent={
            balanceLoadings.getBalances ? (
              ""
            ) : (
              <div style={{ margin: "24px 0" }}>No Balance Founded!</div>
            )
          }
          noHeader
          pagination
          columns={columns}
          paginationPerPage={balancePaginates.per_page}
          className="react-dataTable"
          sortIcon={<ChevronDown size={10} />}
          paginationComponent={CustomPagination}
          data={balanceList}
          theme={skin === "dark" ? "darkTheme" : ""}
        />
        {balanceLoadings.getBalances ? (
          <div className="datatable_loading_cover">
            <ProgressLoading />
          </div>
        ) : null}
      </div>
      {/* delete modal */}
      <Confirm
        visible={deleteModal}
        setVisible={setDeleteModal}
        title={"Are you sure you want to delete this balance?"}
        noAction={() => dispatch(setDeleteModal(null))}
        noColor={"secondary"}
        noTitle={"Cancel"}
        yesLoading={balanceLoadings.deleteBalance}
        yesAction={() => {
          deleteBalance(selectedBalance.Name, filters);
        }}
        yesColor={"danger"}
        yesTitle={"Delete"}
        type={"global"}
        size={"md"}
      />
    </Fragment>
  );
};
export default AllBalances;
